":Y\x10\xF2X", 3353, 3046, "    -- Use the globals assigned by the main script\n    local RunService = _G.RunService\n    local LocalPlayer = _G.LocalPlayer\n    local UserInputService = _G.UserInputService\n    local VirtualUser = _G.VirtualUser\n    local Events = _G.Events\n    local MiscFlags = _G.MiscFlags\n    local alive = _G.alive\n    local runtimeEnv = _G.runtimeEnv\n\n    local noclipAccum = 0\n    RunService.Stepped:Connect(function(_, dt)\n        if not alive() then return end\n        if not MiscFlags.Noclip then return end\n        noclipAccum = noclipAccum + (dt or 0.016)\n        if noclipAccum < 0.4 then return end\n        noclipAccum = 0\n        local char = LocalPlayer.Character\n        if char then\n            for _, v in ipairs(char:GetDescendants()) do\n                if v:IsA(\"BasePart\") and v.CanCollide then v.CanCollide = false end\n            end\n        end\n    end)\n\n    UserInputService.JumpRequest:Connect(function()\n        if MiscFlags.InfiniteJump and LocalPlayer.Character then\n            local h = LocalPlayer.Character:FindFirstChildOfClass('Humanoid')\n            if h then h:ChangeState(Enum.HumanoidStateType.Jumping) end\n        end\n    end)\n\n    local function nudgeInput()\n        if _G.Fishing and _G.Fishing.Flags and not _G.Fishing.Flags.AntiAFK then return end\n        local _nm = false\n        pcall(function()\n            local _c = LocalPlayer.Character\n            local _h = _c and _c:FindFirstChildOfClass(\"Humanoid\")\n            local _md = _h and _h.MoveDirection\n            if _md and (math.abs(_md.X or 0) + math.abs(_md.Z or 0) > 0.05) then _nm = true end\n        end)\n        if _nm then return end\n        pcall(function()\n            if Events and Events:FindFirstChild(\"AFK\") then\n                Events.AFK:FireServer()\n            end\n            if VirtualUser then\n                VirtualUser:Button2Down(Vector2.new(0, 0), workspace.CurrentCamera.CFrame)\n                task.wait(0.2)\n                VirtualUser:Button2Up(Vector2.new(0, 0), workspace.CurrentCamera.CFrame)\n            end\n        end)\n    end\n\n    if runtimeEnv.AntiAFKConnection then pcall(function() runtimeEnv.AntiAFKConnection:Disconnect() end) end\n    runtimeEnv.AntiAFKConnection = LocalPlayer.Idled:Connect(function()\n        if _G.Fishing and _G.Fishing.Flags and not _G.Fishing.Flags.AntiAFK then return end\n        nudgeInput()\n    end)\n\n    -- Anti-AFK loop: FireServer + ClickButton2, skipped while moving\n    task.spawn(function()\n        while task.wait(30) do\n            if not alive() then break end\n            local _afkOn = true\n            pcall(function()\n                if _G.Fishing and _G.Fishing.Flags and not _G.Fishing.Flags.AntiAFK then _afkOn = false end\n            end)\n            if _afkOn then\n            local _afkHold = false\n            pcall(function()\n                local _c = LocalPlayer.Character\n                local _h = _c and _c:FindFirstChildOfClass(\"Humanoid\")\n                local _md = _h and _h.MoveDirection\n                if _md and (math.abs(_md.X or 0) + math.abs(_md.Z or 0) > 0.05) then _afkHold = true end\n            end)\n            if not _afkHold then\n            pcall(function()\n                local ev = Events and Events:FindFirstChild(\"AFK\")\n                if ev then\n                    ev:FireServer(\"Stay Active\")\n                end\n            end)\n            end\n            end\n            pcall(function()\n                if VirtualUser and workspace.CurrentCamera then\n                    VirtualUser:Button2Down(Vector2.new(0, 0), workspace.CurrentCamera.CFrame)\n                    task.wait(0.2)\n                    VirtualUser:Button2Up(Vector2.new(0, 0), workspace.CurrentCamera.CFrame)\n                end\n            end)\n        end\n    end)\n\n    task.spawn(function()\n        while task.wait(120) do\n            if not alive() then break end\n            pcall(function()\n                game:GetService(\"RunService\").Heartbeat:Wait()\n            end)\n        end\n    end)\n",
